const empresa = $('🏢 Obtener Empresa G54').item.json.data;
const keywords = $('🔑 Obtener Keywords Pendientes').item.json.data || [];

// Tomar primera keyword pendiente
const kw = keywords[0];
const keyword = kw.keyword;
const intencion = kw.intencion || 'informacional';
const keyword_id = kw.id;

// Detectar idioma
const spanishMarkers = ['como', 'donde', 'mejor', 'precio', 'que', 'cuanto', 'del', 'de', 'en', 'para', 'cajas', 'madera', 'embalaje', 'servicio', 'comprar', 'encontrar'];
const kwLower = keyword.toLowerCase();
const esEspanol = /[áéíóúüñ]/i.test(keyword) || spanishMarkers.some(w => kwLower.split(' ').includes(w));
const idioma = esEspanol ? 'Español' : 'Inglés';

const website = empresa.website || 'https://cratingexpress.com';
const ciudad = empresa.base_city || 'Doral / Miami, Florida';
const propuesta = empresa.value_proposition || '';
const descripcion = empresa.description || '';
const certificacion = empresa.certification || 'ISPM-15';
const telefono = (empresa.phones || [])[0] || '+1 (786) 558-6007';
const targetKws = (empresa.target_keywords || []).slice(0, 6).join(', ');

const intentMap = {
  'informacional': 'Artículo educativo que responde la pregunta principal de forma directa en el segundo párrafo (bloque AEO). Incluye datos técnicos, ejemplos prácticos y al menos 2 subpreguntas en la sección FAQ.',
  'transaccional': 'Artículo orientado a conversión. Explica el servicio, proceso de pedido, ventajas clave y por qué elegir Crating Express. CTA con URL al menos dos veces: en la mitad y al final.',
  'local': 'Artículo SEO local. Menciona explícitamente Miami, Doral, South Florida y Miami-Dade. Incluye área de cobertura, dirección y tiempo de entrega local.',
  'comercial': 'Artículo de evaluación. Destaca ventajas competitivas, ISPM-15, entrega mismo día y personalización a medida. Responde por qué Crating Express es la mejor opción en Miami.'
};
const instruccionIntent = intentMap[intencion] || intentMap['informacional'];

const instrES = `Genera un artículo SEO completo en HTML para la keyword: "${keyword}" (intención: ${intencion}).

EMPRESA:
- Nombre: ${empresa.name}
- Descripción: ${descripcion}
- Propuesta de valor: ${propuesta}
- Ubicación: ${ciudad}
- Certificación: ${certificacion}
- Teléfono: ${telefono}
- Web: ${website}
- Keywords secundarias: ${targetKws}

INSTRUCCIONES: ${instruccionIntent}

ESTRUCTURA OBLIGATORIA:
1. H1 con keyword principal exacta
2. Párrafo de introducción (keyword en primeras 100 palabras)
3. BLOQUE AEO — respuesta directa en 2-3 oraciones a lo que busca el usuario
4. H2 — Sección 1 (subtema relacionado con keyword secundaria)
5. H2 — Sección 2 (datos, proceso o casos de uso)
6. H2 — Sección 3 (señal GEO: Miami, Doral, South Florida)
7. H2 — FAQ (3 preguntas en formato h3 + p)
8. CTA final con enlace a ${website} y mención de ${telefono}

REGLAS:
- 800-1200 palabras — HTML limpio: h1, h2, h3, p, ul, li, strong
- NO incluyas html, head, body ni CSS
- Menciona ISPM-15 y entrega mismo día cuando sea relevante

RESPONDE SOLO CON JSON VÁLIDO:
{"titulo":"H1 de 50-65 chars","meta_descripcion":"meta de 145-155 chars con keyword","contenido_html":"HTML completo"}`;

const instrEN = `Generate a complete SEO article in HTML for the keyword: "${keyword}" (intent: ${intencion}).

COMPANY:
- Name: ${empresa.name}
- Description: ${descripcion}
- Value proposition: ${propuesta}
- Location: ${ciudad}
- Certification: ${certificacion}
- Phone: ${telefono}
- Website: ${website}
- Secondary keywords: ${targetKws}

INSTRUCTIONS: ${instruccionIntent}

MANDATORY STRUCTURE:
1. H1 with exact main keyword
2. Introduction paragraph (keyword in first 100 words)
3. AEO BLOCK — direct 2-3 sentence answer to the user query
4. H2 — Section 1 (secondary keyword topic)
5. H2 — Section 2 (data, process or use cases)
6. H2 — Section 3 (GEO signal: Miami, Doral, South Florida)
7. H2 — FAQ (3 questions in h3 + p format)
8. Final CTA with link to ${website} and mention of ${telefono}

RULES:
- 800-1200 words — clean HTML: h1, h2, h3, p, ul, li, strong
- Do NOT include html, head, body or CSS
- Mention ISPM-15 certified wood and same-day delivery when relevant

RESPOND ONLY WITH VALID JSON:
{"titulo":"H1 title 50-65 chars","meta_descripcion":"meta description 145-155 chars","contenido_html":"full article HTML"}`;

const promptSistema = idioma === 'Español'
  ? 'Eres un redactor experto en SEO, AEO y GEO para empresas de servicios industriales en Miami, Florida.'
  : 'You are an expert SEO, AEO and GEO content writer for industrial service businesses in Miami, Florida.';

const promptUsuario = idioma === 'Español' ? instrES : instrEN;

return [{ json: { keyword_id, keyword, intencion, idioma, promptSistema, promptUsuario } }];

// Soporta respuesta de Gemini Y Groq/OpenAI
let rawText = '';

if ($json.candidates && $json.candidates.length > 0) {
  rawText = $json.candidates[0].content.parts[0].text;
} else if ($json.choices && $json.choices.length > 0) {
  rawText = $json.choices[0].message.content;
} else {
  throw new Error('No se obtuvo respuesta válida de ninguna IA');
}

rawText = rawText.trim();
if (rawText.startsWith('```json')) rawText = rawText.slice(7);
if (rawText.startsWith('```')) rawText = rawText.slice(3);
if (rawText.endsWith('```')) rawText = rawText.slice(0, -3);
rawText = rawText.trim();

let articulo;
try {
  articulo = JSON.parse(rawText);
} catch (e) {
  const match = rawText.match(/\{[\s\S]+\}/);
  if (match) articulo = JSON.parse(match[0]);
  else throw new Error('No se pudo parsear JSON: ' + rawText.slice(0, 200));
}

const ctx = $('🔧 Preparar Contexto').item.json;

return [{ json: {
  keyword_id: ctx.keyword_id,
  keyword: ctx.keyword,
  intencion: ctx.intencion,
  idioma: ctx.idioma,
  titulo: articulo.titulo || '',
  meta_descripcion: articulo.meta_descripcion || articulo.meta_description || '',
  contenido_html: articulo.contenido_html || articulo.html || ''
} }];
